(()=>{const body=document.body,header=document.querySelector('.site-header'),backdrop=document.querySelector('[data-backdrop]'),drawer=document.querySelector('[data-mobile-drawer]');const setLocked=v=>body.classList.toggle('is-locked',v);const closePanels=()=>{document.querySelectorAll('[data-menu-dropdown]').forEach(p=>p.setAttribute('aria-hidden','true'));document.querySelectorAll('[data-menu-item]').forEach(b=>b.setAttribute('aria-expanded','false'));if(backdrop)backdrop.classList.remove('is-visible');setLocked(false)};document.addEventListener('click',e=>{const t=e.target.closest('[data-menu-item]');if(t){const id=t.getAttribute('aria-controls');const p=document.getElementById(id);const open=t.getAttribute('aria-expanded')==='true';closePanels();if(!open&&p){p.setAttribute('aria-hidden','false');t.setAttribute('aria-expanded','true');backdrop&&backdrop.classList.add('is-visible');setLocked(true)}return}if(!e.target.closest('[data-menu-dropdown]')&& !e.target.closest('[data-mobile-drawer]')&&!e.target.closest('[data-menu-item]'))closePanels()});document.addEventListener('keydown',e=>{if(e.key==='Escape'){closePanels();drawer&&drawer.classList.remove('is-open');setLocked(false)}});if(backdrop)backdrop.addEventListener('click',()=>{closePanels();drawer&&drawer.classList.remove('is-open')});if(header){const obs=new IntersectionObserver(([entry])=>header.classList.toggle('is-scrolled',!entry.isIntersecting),{threshold:1});obs.observe(document.querySelector('#page-start')||document.body)}document.addEventListener('mouseover',e=>{const rail=e.target.closest('[data-rail-item]');if(!rail)return;const panel=rail.closest('[data-menu-dropdown]');if(!panel)return;const key=rail.getAttribute('data-rail-item');panel.querySelectorAll('[data-rail-content]').forEach(s=>s.classList.toggle('is-active',s.getAttribute('data-rail-content')===key));panel.querySelectorAll('[data-rail-item]').forEach(b=>b.setAttribute('aria-pressed',b===rail?'true':'false'))});document.addEventListener('focusin',e=>{const rail=e.target.closest('[data-rail-item]');if(rail)rail.dispatchEvent(new MouseEvent('mouseover',{bubbles:true}))});document.querySelectorAll('[data-filter]').forEach(group=>{const cards=[...document.querySelectorAll('[data-filter-card]')];group.addEventListener('click',e=>{const btn=e.target.closest('button[data-filter-value]');if(!btn)return;const value=btn.dataset.filterValue;group.querySelectorAll('button').forEach(b=>b.classList.toggle('is-active',b===btn));cards.forEach(card=>card.hidden=value!=='all'&&card.dataset.filterCard!==value)})});document.querySelectorAll('[data-compare]').forEach(section=>{const range=section.querySelector('input[type="range"]'),before=section.querySelector('[data-before]'),after=section.querySelector('[data-after]');if(range&&before&&after){const update=()=>{const value=range.value;before.style.clipPath=`inset(0 ${100-value}% 0 0)`;after.style.clipPath=`inset(0 0 0 ${value}%)`};range.addEventListener('input',update);update()}});document.querySelectorAll('[data-mobile-toggle]').forEach(btn=>btn.addEventListener('click',()=>{const open=drawer.classList.toggle('is-open');btn.setAttribute('aria-expanded',open?'true':'false');backdrop&&backdrop.classList.toggle('is-visible',open);setLocked(open)}));})();
